import"../strings.m.js";import{loadTimeData}from"chrome://resources/js/load_time_data.js";import{getRequiredElement}from"chrome://resources/js/util_ts.js";const tableCreationClosuresQueue=[];const STANDARD_DELAY_MS=32;let multilineRowsCount=0;let expandedRowsCount=0;function updateGlobalExpandButtonStates(){const hasExpanded=expandedRowsCount>0;const hasCollapsed=multilineRowsCount-expandedRowsCount>0;if(hasExpanded&&hasCollapsed){getRequiredElement("expandAllBtn").ariaPressed="mixed";getRequiredElement("collapseAllBtn").ariaPressed="mixed"}else if(hasExpanded&&!hasCollapsed){getRequiredElement("expandAllBtn").ariaPressed="true";getRequiredElement("collapseAllBtn").ariaPressed="false"}else if(!hasExpanded&&hasCollapsed){getRequiredElement("expandAllBtn").ariaPressed="false";getRequiredElement("collapseAllBtn").ariaPressed="true"}else{getRequiredElement("expandAllBtn").ariaPressed="false";getRequiredElement("collapseAllBtn").ariaPressed="false"}}function getValueDivForButton(button){return getRequiredElement(button.id.substr(0,button.id.length-4))}function getButtonForValueDiv(valueDiv){return getRequiredElement(valueDiv.id+"-btn")}function expand(button,valueDiv,delayFactor){button.textContent=loadTimeData.getString("logsMapPageCollapseBtn");const valueCell=valueDiv.parentNode;valueCell.removeAttribute("aria-hidden");valueCell.firstChild.hidden=false;setTimeout((function(){valueCell.className="number-expanded";valueCell.firstChild.hidden=true}),STANDARD_DELAY_MS*delayFactor);expandedRowsCount++}function collapse(button,valueDiv){button.textContent=loadTimeData.getString("logsMapPageExpandBtn");valueDiv.parentNode.className="number-collapsed";const valueCell=valueDiv.parentNode;valueCell.setAttribute("aria-hidden","true");expandedRowsCount--}function changeCollapsedStatus(e){const button=e.target;const valueDiv=getValueDivForButton(button);if(valueDiv.parentNode.className==="number-collapsed"){expand(button,valueDiv,1)}else{collapse(button,valueDiv)}updateGlobalExpandButtonStates()}function collapseAll(){const valueDivs=document.body.querySelectorAll(".stat-value");for(let i=0;i<valueDivs.length;++i){if(valueDivs[i].parentNode.className!=="number-expanded"){continue}const button=getButtonForValueDiv(valueDivs[i]);if(button){collapse(button,valueDivs[i])}}updateGlobalExpandButtonStates()}function expandAll(){const valueDivs=document.body.querySelectorAll(".stat-value");for(let i=0;i<valueDivs.length;++i){if(valueDivs[i].parentNode.className!=="number-collapsed"){continue}const button=getButtonForValueDiv(valueDivs[i]);if(button){expand(button,valueDivs[i],i+1)}}updateGlobalExpandButtonStates()}function createNameCell(key){const nameCell=document.createElement("td");nameCell.setAttribute("class","name");const nameDiv=document.createElement("div");nameDiv.id=key;nameDiv.setAttribute("class","stat-name");nameDiv.appendChild(document.createTextNode(key));nameCell.appendChild(nameDiv);return nameCell}function createButtonCell(key,isMultiLine){const buttonCell=document.createElement("td");buttonCell.setAttribute("class","button-cell");if(isMultiLine){const id=`${key}-value-btn`;const button=document.createElement("button");button.setAttribute("id",id);button.setAttribute("aria-controls",""+key+"-value");button.setAttribute("aria-labelledby",`${id} ${key}`);button.onclick=changeCollapsedStatus;button.textContent=loadTimeData.getString("logsMapPageExpandBtn");buttonCell.appendChild(button);multilineRowsCount++}else{buttonCell.setAttribute("aria-hidden","true")}return buttonCell}function createValueCell(key,value,isMultiLine){const valueCell=document.createElement("td");const valueDiv=document.createElement("div");valueDiv.setAttribute("class","stat-value");valueDiv.setAttribute("id",""+key+"-value");valueDiv.appendChild(document.createTextNode(value));if(isMultiLine){valueCell.className="number-collapsed";const loadingContainer=getRequiredElement("spinner-container").cloneNode(true);loadingContainer.setAttribute("id",""+key+"-value-loading");loadingContainer.hidden=true;valueCell.appendChild(loadingContainer);valueCell.setAttribute("aria-hidden","true")}else{valueCell.className="number"}valueCell.appendChild(valueDiv);return valueCell}function createTableRow(key,value){const row=document.createElement("tr");const isMultiLine=value.split("\n").length>2||value.length>1e3;row.appendChild(createNameCell(key));row.appendChild(createButtonCell(key,isMultiLine));row.appendChild(createValueCell(key,value,isMultiLine));return row}function finishPageLoading(){getRequiredElement("collapseAllBtn").onclick=collapseAll;getRequiredElement("expandAllBtn").onclick=expandAll;getRequiredElement("spinner-container").hidden=true;updateGlobalExpandButtonStates()}function processQueue(){const closure=tableCreationClosuresQueue.shift();if(closure){closure()}if(tableCreationClosuresQueue.length>0){setTimeout(processQueue,STANDARD_DELAY_MS)}}function createTableRowWrapper(key,value){return function(){getRequiredElement("detailsTable").appendChild(createTableRow(key,value))}}export function createLogsMapTable(info){for(const key in info){const item=info[key];tableCreationClosuresQueue.push(createTableRowWrapper(item["key"],item["value"]))}tableCreationClosuresQueue.push(finishPageLoading);processQueue()}